{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large polyglycosylated anthracycline-like molecule, showed a peak CSF:plasma ratio of only 0.12 in monkeys with little brain distribution, supporting poor CNS access for similarly large, highly polar glycosylated anthracycline-like compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Vertilmicin, an aminoglycoside with multiple hydroxyl and aminosugar groups, had the lowest brain concentration among all tissues after intravenous dosing in rats, indicating that highly polar aminosugar-containing molecules penetrate the BBB very poorly.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a cardiac glycoside, exhibited a very low CSF/plasma ratio of 0.01-0.03 in dogs, demonstrating that large glycosides do not easily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1, a polar ionizable molecule, showed a tissue-to-blood ratio of about 0.02 in mouse brain by quantitative autoradioluminography, indicating very poor brain penetration for this class of polar compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hesperidin, a flavonoid glycoside, was reported to slowly distribute into mouse brain after oral administration, providing some evidence that certain glycosides can achieve brain exposure, but its smaller size and different scaffold limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar, zwitterionic anthracycline-like glycoside with an aminosugar. Direct evidence from related glycosylated anthracyclines, aminoglycosides, and cardiac glycosides consistently shows poor CSF/brain penetration, and the physicochemical prior is unfavorable; therefore meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct in vivo brain or CSF measurement exists for the query molecule itself.",
    "Exact efflux transporter substrate status is not experimentally confirmed for the query.",
    "Morgan similarities to the evidence molecules are modest (0.19-0.27), so transfer relies on chemical-class analogy rather than close structural identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

